code.text:
variable "tenants" {
  type = map(object({ plan = string }))
  default = {
    acme   = { plan = "pro" }
    globex = { plan = "free" }
  }
}
module "tenant" {
  source   = "./modules/tenant"
  for_each = var.tenants
  name     = each.key
  plan     = each.value.plan
}

locals { tenant = terraform.workspace }
resource "terraform_data" "guard" {
  lifecycle {
    precondition {
      condition     = local.tenant == var.tenant_name
      error_message = "Workspace ${local.tenant} does not match tfvars tenant ${var.tenant_name}."
    }
  }
}
